import { useState } from 'react'
import { T, t } from '../components/T'
import { findNode } from '../lib/content/loader'

/**
 * The quality-control map: six stages, twenty-four components, four states.
 *
 * Generated by hand from the same ledger the vault canvas is generated from
 * (`Origo Quality Control Map — Ledger.md`), and the state of each component
 * lives in its content node's `note` field so a state change is a copy edit
 * rather than a code change.
 *
 * COLOUR IS NEVER THE ONLY CHANNEL. Each component carries its state as a word,
 * as a glyph, and as a fill, and a gap additionally takes the essay's one dashed
 * outline, which means "no check reaches this" exactly as the dashed chips in
 * the vision scenes mean "not a real record". That redundancy is what makes the
 * map readable to a colourblind reader and to a printer.
 *
 * The `gap` key is a storage id and never changes: the content nodes' `note`
 * fields, the CSS classes, and the vault-side spec YAML all address it by that
 * name. Its DISPLAYED word moved from "Gap" to "Fix planned" on 2026-08-07, once
 * every one of the five became a scheduled row on the launch plan, because a hole
 * with a scheduled fix behind it is a different claim from a hole with an opinion
 * behind it. The same rename landed vault-side in `canvas_gen.py`.
 */

const STATES = ['verified', 'partial', 'gap', 'planned'] as const
type State = (typeof STATES)[number]

/** Which components belong to which stage, in pipeline order. */
const STAGES: Array<{ id: string; components: string[] }> = [
  { id: 'qstage-1', components: ['q-1-1', 'q-1-2', 'q-1-3', 'q-1-4', 'q-1-5', 'q-1-6'] },
  { id: 'qstage-2', components: ['q-2-1'] },
  { id: 'qstage-3', components: ['q-3-1', 'q-3-2', 'q-3-3', 'q-3-4', 'q-3-5'] },
  { id: 'qstage-4', components: ['q-4-1', 'q-4-2', 'q-4-3', 'q-4-4', 'q-4-5', 'q-4-6', 'q-4-7'] },
  { id: 'qstage-5', components: ['q-5-1', 'q-5-2'] },
  { id: 'qstage-6', components: ['q-6-1', 'q-6-2', 'q-6-3'] },
]

function stateOf(id: string): State {
  const raw = findNode(id)?.node.note
  return (STATES as readonly string[]).includes(raw ?? '') ? (raw as State) : 'planned'
}

/** The redundant, non-colour channel for each state. */
const GLYPH: Record<State, string> = { verified: '✓', partial: '◐', gap: '○', planned: '·' }
const WORD: Record<State, string> = {
  verified: 'Verified',
  partial: 'Partial',
  gap: 'Fix planned',
  planned: 'Planned',
}

function StateChip({ state }: { state: State }) {
  return (
    <span className={`qm-state qm-state--${state}`}>
      <span className="qm-state__glyph" aria-hidden="true">
        {GLYPH[state]}
      </span>
      {WORD[state]}
    </span>
  )
}

function Component({ id }: { id: string }) {
  const [open, setOpen] = useState(false)
  const state = stateOf(id)
  return (
    <li className={`qm-comp qm-comp--${state} ${open ? 'on' : ''}`}>
      <button
        type="button"
        className="qm-comp__head"
        aria-expanded={open}
        onClick={() => setOpen((o) => !o)}
      >
        <StateChip state={state} />
        <T id={id} field="label" as="span" className="qm-comp__label" />
        <span className="qm-comp__chev" aria-hidden="true">
          {open ? '−' : '+'}
        </span>
      </button>
      {open && (
        <div className="qm-comp__body">
          <span className="qm-comp__body-kicker">
            {state === 'gap'
              ? 'The problem, and the planned fix'
              : 'What this check does not reach'}
          </span>
          <T id={id} field="text" as="p" />
        </div>
      )}
    </li>
  )
}

function Tally({ components }: { components: string[] }) {
  const counts = components.reduce<Record<string, number>>((acc, id) => {
    const s = stateOf(id)
    acc[s] = (acc[s] ?? 0) + 1
    return acc
  }, {})
  return (
    <span className="qm-tally">
      {STATES.filter((s) => counts[s]).map((s) => (
        <span key={s} className={`qm-tally__bit qm-tally__bit--${s}`}>
          <span aria-hidden="true">{GLYPH[s]}</span>
          {counts[s]}
          <span className="vs-sr-only"> {WORD[s]}</span>
        </span>
      ))}
    </span>
  )
}

export function QualityMap() {
  return (
    <div className="qm">
      <div className="qm-legend" aria-label={t('qmap-legend-title', 'label')}>
        <T id="qmap-legend-title" field="label" as="span" className="qm-legend__title" />
        <ul className="qm-legend__list">
          {STATES.map((s) => (
            <li key={s} className="qm-legend__item">
              <StateChip state={s} />
              <T id={`qmap-state-${s}`} field="text" as="span" className="qm-legend__text" />
            </li>
          ))}
        </ul>
      </div>

      <ol className="qm-stages">
        {STAGES.map((stage, i) => (
          <li className="qm-stage" key={stage.id}>
            <div className="qm-stage__head">
              <span className="qm-stage__num" aria-hidden="true">
                {i + 1}
              </span>
              <div className="qm-stage__id">
                <T id={stage.id} field="label" as="h3" className="qm-stage__label" />
                <T id={stage.id} field="text" as="p" className="qm-stage__text" />
              </div>
              <Tally components={stage.components} />
            </div>
            <ul className="qm-comps">
              {stage.components.map((id) => (
                <Component key={id} id={id} />
              ))}
            </ul>
            {i < STAGES.length - 1 && (
              <span className="qm-stage__arrow" aria-hidden="true">
                ↓
              </span>
            )}
          </li>
        ))}
      </ol>
    </div>
  )
}
